import 'package:pusher_client/pusher_client.dart';

void main() {
  var options = PusherOptions(
    host: 'example.com',
    wsPort: 6001,
    encrypted: false,
    auth: PusherAuth('http://example.com/auth', headers: {'Authorization':'Bearer token'}),
  );
  var pusher = PusherClient('YOUR_APP_KEY', options);
  pusher.connect();
  var channel = pusher.subscribe('private-orders');
  channel.bind('order-status-updated', (event) => print(event.data));
}
